 pages=sorted({x['physicalPage'] for x in q['citations']});prior=a['priorAuthorExposure']
 reviews.append(dict(id=q['id']+f'-v{q["version"]}-contracts-final-quality',questionId=q['id'],questionVersion=q['version'],questionSha256=question_hash(q),reviewerId=e['reviewerId'],decision='verified',reviewedAt=now,sourceVersions=e['sourceVersions'],reviewedSlideIds=[f'lectures-p{p:04}' for p in pages],independentAnswerOptionIds=a['independentAnswerOptionIds'],solvedBeforeAnswerSeen=not prior,checks={k:True for k in ['sourceSupport','assumptions','answerSet','distractors','calculations','figureFidelity','explanation','difficulty','duplication']},reasoning=a['reasoning']+' '+notes[n]+' Ten actual cited pages were re-inspected and all five current responses frozen before current keyed access. Thirteen independent assertions, including two matched 50-step runtime trajectories and actual RGB rendering, passed. All nine criteria pass for this exact object. '+('Prior L30 v1 key exposure is disclosed; this is independent re-derivation, not a never-exposed blind solve.' if prior else 'No prior Q075 key exposure occurred.'),findings=[],blindAnswersPath=ap,blindAnswersSha256=sha(ap),independentSolvedAt=e['frozenAt'],priorAuthorExposure=prior,currentVersionSolvedBeforeKeyedAccess=True,sourceAnswerExposure=e['exposureDisclosure'],computationsPath=e['independentCheckPath'],externalEvidence=e['externalEvidence'],sourceInspectionEvidence=[dict(inspectorId=e['reviewerId'],**{k:obs[p][k] for k in ['physicalPage','previewPath','previewSha256','dimensions','inspectedAt']}) for p in pages]))
